import pickle
@pytest.mark.parametrize('body',[b'one',b'',b'two\nthree'])
def test_adjacent_records(body):
    response=httpx.Response(200,content=body,request=httpx.Request('GET','http://case.invalid/cached'),extensions={'callback':lambda:None})
    restored=pickle.loads(pickle.dumps(response))
    assert restored.content==body and restored.text==body.decode()
    assert restored.is_closed and restored.extensions=={}
    with pytest.raises(httpx.StreamConsumed): list(restored.iter_raw())

