@pytest.mark.parametrize('token',['first','second','third'])
@pytest.mark.parametrize('asynchronous',[False,True])
async def test_observed_records(token,asynchronous):
    seen=[]
    class BodyAuth(httpx.Auth):
        requires_response_body=True
        def auth_flow(self,request):
            response=yield request
            request.headers['x-proof']=response.json()['token']
            yield request
    def handler(request):
        seen.append(request.headers.get('x-proof'))
        body=json.dumps({'token':token}).encode() if len(seen)==1 else b'accepted'
        return httpx.Response(401 if len(seen)==1 else 200,stream=AsyncChunks([body[:2],body[2:]]) if asynchronous else SyncChunks([body[:2],body[2:]]))
    if asynchronous:
        async with httpx.AsyncClient(transport=httpx.MockTransport(handler),auth=BodyAuth(),trust_env=False) as client: response=await client.get('http://case.invalid/flow')
    else:
        with httpx.Client(transport=httpx.MockTransport(handler),auth=BodyAuth(),trust_env=False) as client: response=client.get('http://case.invalid/flow')
    assert response.status_code==200 and response.content==b'accepted' and seen==[None,token]

