@pytest.mark.parametrize('duplicate_count',[2,3,4])
def test_observed_records(duplicate_count):
    headers=[]
    for i in range(duplicate_count): headers += [('X-Route','old'+str(i)),('X-Keep-'+str(i),'keep'+str(i))]
    with httpx.Client(headers=headers,trust_env=False) as client:
        request=client.build_request('GET','http://case.invalid/headers',headers={'x-route':'new'})
        assert request.headers.get_list('x-route')==['new']
        for i in range(duplicate_count): assert request.headers['x-keep-'+str(i)]=='keep'+str(i)
        assert client.headers.get_list('x-route')==['old'+str(i) for i in range(duplicate_count)]

