@pytest.mark.parametrize('operation',['single-delete','missing-delete','duplicate-assign'])
def test_adjacent_records(operation):
    headers=httpx.Headers([('X-One','one'),('X-Keep','keep')])
    if operation=='single-delete':
        del headers['x-one']; assert 'x-one' not in headers
    elif operation=='missing-delete':
        with pytest.raises(KeyError): del headers['absent']
        assert headers['x-one']=='one'
    else:
        headers=httpx.Headers([('X-One','one'),('x-one','two'),('X-Keep','keep')])
        headers['X-One']='new'; assert headers.get_list('x-one')==['new']
    assert headers['x-keep']=='keep'

