from http.cookies import SimpleCookie
@pytest.mark.parametrize('pairs',[(('first','1'),('second','2')),(('alpha','a'),('beta','b'),('gamma','g')),(('left','x'),('right','y'))])
def test_observed_records(pairs):
    seen=[]
    def handler(request):
        seen.append(request)
        if len(seen)==1:
            headers=[('Set-Cookie',name+'='+value+'; Path=/; Expires=Wed, 09 Jun 2038 10:18:14 GMT') for name,value in pairs]
            return httpx.Response(200,headers=headers,text='stored')
        return httpx.Response(200,json={'cookie':request.headers.get('cookie','')})
    with httpx.Client(transport=httpx.MockTransport(handler),trust_env=False) as client:
        first=client.get('http://case.invalid/set')
        assert dict(first.cookies)==dict(pairs) and dict(client.cookies)==dict(pairs)
        second=client.get('http://case.invalid/check')
    jar=SimpleCookie(); jar.load(second.json()['cookie'])
    assert {name:m.value for name,m in jar.items()}==dict(pairs)

