@pytest.mark.parametrize('kind',['json','form','raw'])
def test_observed_records(kind):
    captured=[]
    def app(environ,start_response):
        captured.append(environ)
        length=environ.get('CONTENT_LENGTH','0')
        body=environ['wsgi.input'].read(int(length))
        payload={'length':length,'type':environ.get('CONTENT_TYPE'),'body':body.decode(),'mode':environ.get('HTTP_X_MODE')}
        start_response('200 OK',[('Content-Type','application/json')]); return [json.dumps(payload).encode()]
    options={'json':{'x':2}} if kind=='json' else {'data':{'x':'two'}} if kind=='form' else {'content':b'raw-body','headers':{'content-type':'application/octet-stream','x-mode':'keep'}}
    options.setdefault('headers',{})['x-mode']='keep'
    with httpx.Client(transport=httpx.WSGITransport(app),trust_env=False) as client:
        request=client.build_request('POST','http://case.invalid/upload',**options)
        expected_body=request.read().decode()
        result=client.send(request).json()
    assert result=={'length':str(len(expected_body.encode())),'type':request.headers['content-type'],'body':expected_body,'mode':'keep'}
    assert 'HTTP_CONTENT_LENGTH' not in captured[0] and 'HTTP_CONTENT_TYPE' not in captured[0]

