@pytest.mark.parametrize('status',[200,201,418])
def test_adjacent_records(status):
    events=[]
    def one(response): events.append('one'); response.headers['x-hook']='one'
    def two(response): assert response.headers['x-hook']=='one'; events.append('two')
    with httpx.Client(transport=httpx.MockTransport(lambda r:httpx.Response(status,text='sync')),event_hooks={'response':[one,two]},trust_env=False) as client:
        response=client.get('http://case.invalid/hooks')
    assert events==['one','two'] and response.text=='sync' and response.status_code==status

